// Get the version from the webhook trigger payload
const webhookData = $('Webhook — GitHub Release').first().json;
const targetVersion = webhookData.body?.version || webhookData.version;

// Get all rows from Google Sheets
const allRows = $input.all();

// Group rows by version
const byVersion = {};
for (const row of allRows) {
  const v = row.json.Version;
  if (!v) continue;
  if (!byVersion[v]) byVersion[v] = [];
  byVersion[v].push(row.json);
}

// Use the version from the webhook if provided, otherwise pick the most recent
let selectedVersion = targetVersion;
if (!selectedVersion || !byVersion[selectedVersion]) {
  // Sort versions descending (semver-aware numeric sort)
  const versions = Object.keys(byVersion).sort((a, b) => {
    const pa = a.split('.').map(Number);
    const pb = b.split('.').map(Number);
    for (let i = 0; i < 3; i++) {
      if ((pa[i] || 0) !== (pb[i] || 0)) return (pb[i] || 0) - (pa[i] || 0);
    }
    return 0;
  });
  selectedVersion = versions[0];
}

const changes = byVersion[selectedVersion] || [];

if (changes.length === 0) {
  throw new Error('No changes found for version ' + selectedVersion);
}

const releaseDate = changes[0].Fecha || new Date().toISOString().split('T')[0];

// Group by type for a structured prompt
const features = changes.filter(c => c.Tipo === 'feature');
const improvements = changes.filter(c => c.Tipo === 'improvement');
const fixes = changes.filter(c => c.Tipo === 'fix');

const formatList = (items) =>
  items.map(c => '  - [' + c.Componente + '] ' + c.Cambio_Tecnico).join('\n');

const prompt =
  'Sos un Product Manager experto en comunicar cambios de software a usuarios no t\u00e9cnicos.\n\n' +
  'Tu tarea es transformar este changelog t\u00e9cnico de la versi\u00f3n ' + selectedVersion + ' de TaskFlow ' +
  '(una herramienta de gesti\u00f3n de proyectos) en release notes atractivas y f\u00e1ciles de entender para usuarios finales.\n\n' +
  'FECHA DE LANZAMIENTO: ' + releaseDate + '\n' +
  'VERSI\u00d3N: ' + selectedVersion + '\n\n' +
  'CHANGELOG T\u00c9CNICO:\n\n' +
  'NUEVAS FUNCIONALIDADES (' + features.length + '):\n' + (formatList(features) || '  (ninguna)') + '\n\n' +
  'MEJORAS (' + improvements.length + '):\n' + (formatList(improvements) || '  (ninguna)') + '\n\n' +
  'CORRECCIONES (' + fixes.length + '):\n' + (formatList(fixes) || '  (ninguna)') + '\n\n' +
  'INSTRUCCIONES DE TRANSFORMACI\u00d3N:\n' +
  '1. Cada cambio t\u00e9cnico debe expresarse en lenguaje simple que cualquier usuario entienda\n' +
  '2. Enfoc\u00e1te en el BENEFICIO para el usuario, no en el detalle t\u00e9cnico\n' +
  '3. Agrup\u00e1 por tipo: \u2728 Nuevas funcionalidades, \ud83d\ude80 Mejoras, \ud83d\udc1b Correcciones\n' +
  '4. Agrega emojis relevantes en cada punto para hacerlo visual y atractivo\n' +
  '5. M\u00e1ximo 2 oraciones por cambio \u2014 directo y claro\n' +
  '6. Empez\u00e1 con un t\u00edtulo llamativo y un intro de 1-2 oraciones resumiendo la versi\u00f3n\n' +
  '7. Cerr\u00e1 con una frase motivadora de 1 oraci\u00f3n invitando a actualizar\n\n' +
  'FORMATO FINAL:\n' +
  'T\u00edtulo y intro\n\n' +
  '\u2728 Nuevas funcionalidades\n[lista]\n\n' +
  '\ud83d\ude80 Mejoras\n[lista]\n\n' +
  '\ud83d\udc1b Correcciones\n[lista]\n\nCierre';

return [{ json: { prompt, version: selectedVersion, releaseDate, totalChanges: changes.length } }];

// Extract the AI-generated release notes from OpenAI response
const openAiResponse = $json;
const releaseNotes = openAiResponse.choices[0].message.content;

// Get metadata from the previous Code node
const filterNode = $('Code \u2014 Filter Latest Version').first().json;
const version = filterNode.version;
const releaseDate = filterNode.releaseDate;
const totalChanges = filterNode.totalChanges;

const message =
  '\ud83d\ude80 *TaskFlow ' + version + ' est\u00e1 disponible*\n' +
  '\ud83d\udcc5 ' + releaseDate + ' \u00b7 ' + totalChanges + ' cambios\n\n' +
  releaseNotes +
  '\n\n_Generado autom\u00e1ticamente por n8n + OpenAI_';

return [{ json: { message, version } }];
